/**
 * @module services/fileStore
 * Where attachment bytes live, behind one interface:
 *
 * - `LocalFileStore`    a folder on disk (development; default `server/uploads/`).
 * - `SupabaseFileStore` a PRIVATE Supabase Storage bucket accessed with the service-role key
 *                       through the Storage REST API (production: serverless hosts have no
 *                       persistent disk). The key never reaches the browser.
 *
 * Stored names are generated by the server (`<uuid>.<ext>`); `isSafeStoredName` still
 * rejects anything that could escape the folder/bucket (defense in depth).
 */
import { resolve, SEPARATOR } from "@std/path";

export interface FileStore {
  readonly kind: "local" | "supabase";
  put(name: string, bytes: Uint8Array, contentType: string): Promise<void>;
  /** File content, or null when it does not exist. */
  get(name: string): Promise<Uint8Array | null>;
  exists(name: string): Promise<boolean>;
  remove(names: readonly string[]): Promise<void>;
}

/** Generates a storage name that contains no user input. */
export function newStoredName(extension: string): string {
  return `${crypto.randomUUID()}${extension}`;
}

/** Only plain file names (no separators, no `..`). Legacy names such as `<uuid>-file.pdf` stay valid. */
export function isSafeStoredName(name: string): boolean {
  return /^[A-Za-z0-9][A-Za-z0-9._-]{0,250}$/.test(name) && !name.includes("..");
}

// ---------- Local folder ----------

export function createLocalFileStore(directory: string): FileStore {
  const root = resolve(directory);
  const pathOf = (name: string): string | null => {
    if (!isSafeStoredName(name)) return null;
    const path = resolve(root, name);
    return path.startsWith(root + SEPARATOR) ? path : null;
  };

  return {
    kind: "local",
    async put(name, bytes) {
      const path = pathOf(name);
      if (!path) throw new Error("Unsafe stored name.");
      await Deno.mkdir(root, { recursive: true });
      await Deno.writeFile(path, bytes, { createNew: true });
    },
    async get(name) {
      const path = pathOf(name);
      if (!path) return null;
      try {
        return await Deno.readFile(path);
      } catch (error) {
        if (error instanceof Deno.errors.NotFound) return null;
        throw error;
      }
    },
    async exists(name) {
      const path = pathOf(name);
      if (!path) return false;
      try {
        return (await Deno.stat(path)).isFile;
      } catch {
        return false;
      }
    },
    async remove(names) {
      for (const name of names) {
        const path = pathOf(name);
        if (!path) continue;
        try {
          await Deno.remove(path);
        } catch {
          // Already gone.
        }
      }
    },
  };
}

// ---------- Supabase Storage ----------

export interface SupabaseStoreOptions {
  /** Project URL, e.g. https://abcd.supabase.co */
  url: string;
  /** Service-role key (server only). */
  serviceKey: string;
  /** Private bucket name. */
  bucket: string;
  /** Injectable for tests. */
  fetchFn?: typeof fetch;
}

export function createSupabaseFileStore(options: SupabaseStoreOptions): FileStore {
  const base = `${options.url.replace(/\/+$/, "")}/storage/v1/object`;
  const bucket = encodeURIComponent(options.bucket);
  const doFetch = options.fetchFn ?? fetch;
  const auth = { Authorization: `Bearer ${options.serviceKey}`, apikey: options.serviceKey };
  const objectUrl = (name: string) => `${base}/${bucket}/${encodeURIComponent(name)}`;

  return {
    kind: "supabase",
    async put(name, bytes, contentType) {
      if (!isSafeStoredName(name)) throw new Error("Unsafe stored name.");
      const response = await doFetch(objectUrl(name), {
        method: "POST",
        headers: { ...auth, "Content-Type": contentType, "x-upsert": "false" },
        body: new Blob([bytes as Uint8Array<ArrayBuffer>], { type: contentType }),
      });
      if (!response.ok) throw new Error(`Storage upload failed with status ${response.status}.`);
      await response.body?.cancel();
    },
    async get(name) {
      if (!isSafeStoredName(name)) return null;
      const response = await doFetch(objectUrl(name), { headers: auth });
      if (response.status === 400 || response.status === 404) {
        await response.body?.cancel();
        return null;
      }
      if (!response.ok) throw new Error(`Storage download failed with status ${response.status}.`);
      return new Uint8Array(await response.arrayBuffer());
    },
    async exists(name) {
      if (!isSafeStoredName(name)) return false;
      const response = await doFetch(objectUrl(name), { method: "HEAD", headers: auth });
      await response.body?.cancel();
      return response.ok;
    },
    async remove(names) {
      const safe = names.filter(isSafeStoredName);
      if (safe.length === 0) return;
      const response = await doFetch(`${base}/${bucket}`, {
        method: "DELETE",
        headers: { ...auth, "Content-Type": "application/json" },
        body: JSON.stringify({ prefixes: safe }),
      });
      await response.body?.cancel();
    },
  };
}
